{
  "summary": "This paper investigates the impact of reference choice on benchmark scores in a multilingual span extraction task for personally identifiable information (PII). By holding system outputs fixed and varying the reference, the study finds that scores can shift significantly, with changes up to 7.55 F1 points in one language. The authors propose a method to measure reference sensitivity and recommend reporting a reference-sensitivity band alongside benchmark scores.",
  "items": {
    "chk_problem": {
      "value": "The paper examines how benchmark scores are affected by the choice of reference, which is often treated as a fixed property but can vary based on annotation processes.",
      "paper_quote": "A benchmark score compares a system output against a reference, and methodological attention falls almost entirely on the first term. We measure the second."
    },
    "chk_method": {
      "value": "The study holds system outputs fixed and varies the reference to measure the impact of reference choice on benchmark scores.",
      "paper_quote": "We invert the usual arrangement: instead of varying the system and fixing the reference, we hold the system output fixed and vary the reference, so any movement is attributable to reference choice alone."
    },
    "chk_data": {
      "value": "The dataset is a multilingual benchmark for PII span extraction, covering six languages and 24,939 prompts, with retained annotation records including two annotator labellings and an expert re-annotation.",
      "paper_quote": "We use the annotation record of a production multilingual benchmark for personally identifiable information (PII) extraction, covering six languages and 24,939 prompts."
    },
    "chk_setup": {
      "value": "The study uses the audited subset of 2,628 prompts where all four labellings coexist, scoring outputs against two references under strict and relaxed matching rules.",
      "paper_quote": "Every measurement is computed on the audited subset of Section 2.3, the only items on which all four labellings coexist."
    },
    "chk_primary_result": {
      "value": "Exchanging the reference moves the score by 4.95 F1 points for one annotator’s output and 2.00 for the other (95% CIs [3.23, 6.27] and [0.26, 3.37]).",
      "paper_quote": "The score moves by 4.95 F1 points for one output and 2.00 for the other (95% CIs [3.23, 6.27] and [0.26, 3.37])."
    },
    "chk_secondary_result": {
      "value": "The comparison between two outputs moves as well, with a paired interaction of +2.95 points (CI [+1.97, +3.87]), which changes one language’s margin outright.",
      "paper_quote": "The comparison between two outputs moves as well: the paired interaction between reference and system is +2.95 points (CI [+1.97, +3.87]), survives correction for multiple testing, and changes one language’s margin outright."
    },
    "chk_baseline": {
      "value": "The study compares scores obtained using the delivered gold reference versus the reviewer gold reference.",
      "paper_quote": "The delivered gold and the expert re-annotation are both defensible; a practitioner could have adopted either."
    },
    "chk_conclusion": {
      "value": "Benchmark scores measure both system performance and reference choice, and benchmarks should report a reference-sensitivity band alongside scores.",
      "paper_quote": "We suggest benchmarks report a reference-sensitivity band alongside the score."
    },
    "chk_limitation": {
      "value": "The study is based on a single annotation record, and the magnitude of reference sensitivity for model outputs remains an empirical question.",
      "paper_quote": "These are measurements of one annotation record, not a general law, and a pipeline with a neutral aggregation rule would show less."
    }
  }
}
